import java.util.*;
import java.io.*;

public class Main {
    static long[] stopSequence(String direction, long current, long[] floors) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        String direction = st.nextToken();
        long current = Long.parseLong(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        long[] floors = new long[m];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < m; i++) floors[i] = Long.parseLong(st.nextToken());
        long[] res = stopSequence(direction, current, floors);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
